TOK = {
 '@G@':'#0B0A09', '@T@':'#F7F3EC', '@M@':'#7C766D', '@A@':'#FF5C1A',
 '@L@':'#241F1B', '@P@':'#141210', '@P2@':'#191512',
 '@KUFI@':"'Thmanyah','Geeza Pro',Tahoma,sans-serif",
 '@BODY@':"'Thmanyah','Geeza Pro',Tahoma,sans-serif",
 '@MONO@':"'IBM Plex Mono',ui-monospace,monospace",
}
def sub(s):
    for k,v in TOK.items(): s = s.replace(k,v)
    return s

