TAIL = "</x-dc>\n</body>\n</html>\n"

def slide(num, cap, inner, center=False):
    just = 'center' if center else 'space-between'
    head = '' if center else (
      '  <div style="display: flex; justify-content: space-between; align-items: center;">\n'
      '    <div style="font-family: @MONO@; font-size: 15px; letter-spacing: 0.16em; color: @M@;">' + num + '</div>\n'
      '    <div style="font-family: @BODY@; font-size: 18px; color: @M@;">' + cap + '</div>\n'
      '  </div>\n')
    foot = '' if center else (
      '  <div style="display: flex; justify-content: space-between; align-items: flex-end; '
      'border-top: 1px solid @L@; padding-top: 20px;">\n'
      '    <div style="font-family: @MONO@; font-size: 14px; letter-spacing: 0.18em; color: @L@;"' + (' dir="ltr"' if num.isdigit() else '') + '>' + (num + ' / 16' if num.isdigit() else 'ملحق') + '</div>\n'
      '    <div style="font-family: @KUFI@; font-size: 16px; font-weight: 700; color: @M@;">كامن</div>\n'
      '  </div>\n')
    return sub(HEAD +
      '<div dir="rtl" style="width: 1600px; height: 900px; box-sizing: border-box; background: @G@; color: @T@; '
      'font-family: @BODY@; padding: 80px 104px; display: flex; flex-direction: column; justify-content: ' + just + '; '
      'overflow: hidden;">\n' + head + inner + foot + '</div>\n' + TAIL)

def H(t, size=92, color='@T@', lh=1.30):
    return ('  <div style="font-family: @KUFI@; font-weight: 700; font-size: ' + str(size) + 'px; line-height: '
            + str(lh) + '; color: ' + color + '; letter-spacing: -0.01em;">' + t + '</div>\n')
def P(t, size=30, color='@M@', mt=24, lh=1.75):
    return ('  <div style="font-size: ' + str(size) + 'px; font-weight: 300; line-height: ' + str(lh)
            + '; color: ' + color + '; margin-top: ' + str(mt) + 'px;">' + t + '</div>\n')
def BAR(w=180, mb=32):
    return '  <div style="width: ' + str(w) + 'px; height: 10px; background: @A@; margin-bottom: ' + str(mb) + 'px;"></div>\n'

