    '    <div style="border:1px solid ' + UI['line'] + ';background:' + UI['paper'] + ';border-radius:6px;overflow:hidden;">\n'
    '      <div style="position:relative;background:' + UI['chrome'] + ';border-bottom:1px solid ' + UI['line'] + ';padding:6px 12px;">\n'
