    '      </div>\n'
    '      <div style="display:grid;' + cols + 'gap:8px;font-family:@BODY@;font-size:12px;color:' + UI['dim'] + ';'
    'background:' + UI['side'] + ';padding:5px 12px;border-bottom:1px solid ' + UI['line'] + ';">\n'
    '        <div>الوصف</div><div>المدة</div><div>المعيار</div>\n'
