def box(x, y, w, h, title, sub=None, accent=False, dashed=False, fs=19, img=None):
    stroke = '#FF5C1A' if accent else '#3A322B'
    fillc  = 'rgba(255,92,26,0.06)' if accent else '#141210'
    o  = ('<rect x="%d" y="%d" width="%d" height="%d" rx="3" fill="%s" stroke="%s" stroke-width="1.4"%s/>'
          % (x, y, w, h, fillc, stroke, ' stroke-dasharray="5 4"' if dashed else ''))
    if img:
        o += '<image href="%s" x="%d" y="%d" width="56" height="56" preserveAspectRatio="xMidYMid meet"/>' % (img, x+w-64, y+(h-56)/2)
        cx = x + (w-64)/2
    else:
        cx = x + w/2
    ty = y + (h/2 + 7) if not sub else y + h/2 - 4
    o += ('<text x="%.1f" y="%.1f" text-anchor="middle" font-family=%s font-weight="700" font-size="%d" fill="%s">%s</text>'
          % (cx, ty, '"'+KU+'"', fs, '#FF5C1A' if accent else '#F7F3EC', title))
    if sub:
        o += ('<text x="%.1f" y="%.1f" text-anchor="middle" font-family=%s font-size="14" fill="#7C766D">%s</text>'
              % (cx, y + h/2 + 19, '"'+BO+'"', sub))
    return o

